import { handleInquiry } from "./inquiry";
import type { InquiryEnv } from "./throttle";
import { routeLanguage } from "./routing";
import { localeFromPathname } from "../lib/locale";
// Generated by build: only published paths and images can be served.
declare const PAGES_MANIFEST: { paths: string[]; slugs: Record<string, string[]> };
const manifest = PAGES_MANIFEST;
interface Env extends InquiryEnv { ASSETS: { fetch(request: Request): Promise<Response> } }
const pages = new Set<string>(manifest.paths);
const slugs = manifest.slugs as Record<string, string[]>;

export default {
  async fetch(request: Request & { cf?: { country?: string } }, env: Env) {
    const url = new URL(request.url);
    const path = url.pathname;
    if (path === "/api/inquiry" || path === "/api/inquiry/") return handleInquiry(request, env);
    // API paths never enter language routing.
    if (/^\/api(?:\/|$)/.test(path)) return new Response("Not found", { status: 404 });
    const clean = path.replace(/\/$/, "") || "/";
    const language = routeLanguage(request, request.cf?.country);
    if (language) return language;
    if (/^\/(?:es\/)?og$/.test(clean)) {
      if (!["GET", "HEAD"].includes(request.method)) return new Response("Method not allowed", { status: 405 });
      const locale = localeFromPathname(clean);
      const slug = url.searchParams.get("post");
      if (slug && !slugs[locale].includes(slug)) return new Response("Not found", { status: 404 });
      // Serve prebuilt PNG at the original query URL; never generate images here.
      url.pathname = `/social/${locale}/${slug || "home"}.png`;
      url.search = "";
      return env.ASSETS.fetch(new Request(url, { method: request.method }));
    }
    if (pages.has(clean) && path !== clean) {
      url.pathname = clean;
      return new Response(null, { status: 308, headers: { Location: url.href, "Cache-Control": "no-store" } });
    }
    const response = await env.ASSETS.fetch(request);
    if (pages.has(clean)) {
      // English HTML can trigger personalized redirects on subsequent visits.
      // Never let shared browser/CDN caches skip preference evaluation.
      const result = new Response(response.body, response);
      result.headers.set("Cache-Control", "private, no-store");
      result.headers.set("Vary", "Cookie, Accept-Language, User-Agent");
      return result;
    }
    return response;
  },
};
